// El backend ya eligio a quien escribirle, calculo los dias y formateo el
// monto. Aqui solo se abre el arreglo en un item por fiado.
const respuesta = $input.first().json;
const fiados = respuesta.fiados || [];

console.log(`[Cobro de fiados] Pendientes de aviso: ${fiados.length}`);

return fiados.map((f) => {
  console.log(
    `[Cobro de fiados] → ${f.negocio} / ${f.sede} [${f.via}]: ${f.cliente} debe ${f.montoTexto} hace ${f.diasTranscurridos} d`,
  );

  return { json: f };
});

// Un envio fallido no corta el workflow: se registra y se sigue con los demas.
// Ojo: el fiado ya quedo marcado como avisado al consultarlo, asi que este
// aviso concreto no se reintenta manana. Si aparecen fallos repetidos, el
// problema esta en la plantilla o en el numero, no en el envio.
for (const item of $input.all()) {
  const detalle = JSON.stringify(item.json).slice(0, 800);
  console.error('[Cobro de fiados] ERROR de envío:', detalle);
}
return $input.all();
